command:
umask 077
test -z "$(ls -A /home/dev)"
/usr/local/bin/agentd version > /tmp/agentd-version.txt
/usr/local/bin/agentd project-refresh > /tmp/bootstrap-result.json
python3 - <<'BOOTSTRAP_VERIFY'
import hashlib,json,os,pathlib,re,subprocess,sys
try:
 root=pathlib.Path('/home/dev')
 report=json.loads(pathlib.Path('/tmp/bootstrap-result.json').read_bytes())
 saved=root/'.agentd/project-bootstrap.json'
 if report != json.loads(saved.read_bytes()): raise ValueError()
 if report.get('version') != 1 or report.get('state') != 'Ready': raise ValueError()
 if report.get('catalogNamespace') != 'dev-env-system' or report.get('catalogName') != 'dev-env-project-catalog': raise ValueError()
 if report.get('catalogRevision') != os.environ['EXPECTED_CATALOG_SHA256']: raise ValueError()
 if not report.get('catalogUID') or not report.get('catalogResourceVersion'): raise ValueError()
 version=pathlib.Path('/tmp/agentd-version.txt').read_text().strip()
 if '(commit '+os.environ['EXPECTED_SOURCE_COMMIT'][:12]+',' not in version: raise ValueError()
 repos=report.get('repositories',[])
 if len(repos) != 1: raise ValueError()
 repo=repos[0]
 if repo.get('repository') != {'name':'dev-env','github':'thaynes43/dev-env','defaultBranch':'main'}: raise ValueError()
 if repo.get('state') != 'Ready' or not re.fullmatch('[0-9a-f]{40}',repo.get('target','')): raise ValueError()
 clone=root/'repos/dev-env'
 def git(*args): return subprocess.check_output(['git','-C',str(clone),'-c','core.hooksPath=/dev/null','-c','core.fsmonitor=false','-c','core.useReplaceRefs=false',*args],stderr=subprocess.DEVNULL,text=True,timeout=5).strip()
 if git('rev-parse','--path-format=absolute','--git-common-dir') != str(clone/'.git'): raise ValueError()
 if git('rev-parse','--show-toplevel') != str(clone): raise ValueError()
 if git('remote','get-url','--all','origin') != 'https://github.com/thaynes43/dev-env': raise ValueError()
 if git('remote','get-url','--push','--all','origin') != 'https://github.com/thaynes43/dev-env': raise ValueError()
 if git('symbolic-ref','--quiet','HEAD') != 'refs/heads/main': raise ValueError()
 if git('rev-parse','HEAD') != repo['target'] or git('rev-parse','refs/remotes/origin/main') != repo['target']: raise ValueError()
 if git('status','--porcelain=v1','--untracked-files=all'): raise ValueError()
 if (root/'.claude').exists() or (root/'.codex').exists() or (root/'.shared').exists(): raise ValueError()
 print(json.dumps({'state':'Ready','modelFree':True,'podName':os.environ['CHECK_POD_NAME'],'podUID':os.environ['CHECK_POD_UID'],'agentdVersion':version,'catalogUID':report['catalogUID'],'catalogResourceVersion':report['catalogResourceVersion'],'catalogSha256':report['catalogRevision'],'repository':'dev-env','sourceCommit':repo['target'],'receiptSha256':hashlib.sha256(saved.read_bytes()).hexdigest()},sort_keys=True))
except Exception:
 print(json.dumps({'state':'Failed','modelFree':True,'reason':'bootstrap-verification-refused'},sort_keys=True))
 sys.exit(1)
BOOTSTRAP_VERIFY
